 useEffect(()=>{const f=(e:MessageEvent)=>{if(e.source===window&&e.origin===location.origin&&e.data?.type==='SHOPFLOW_IMPORT'&&Array.isArray(e.data.orders)){setPreview(e.data.orders);setTab('orders');window.postMessage({type:'SHOPFLOW_IMPORT_RECEIVED'},location.origin);tell('Đã nhận dữ liệu extension. Kiểm tra trước khi lưu vào shop đang chọn.');}};window.addEventListener('message',f);return()=>window.removeEventListener('message',f);},[]);
