 async function mutate(path:string,body:any){return api(endpoint(path),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});}
 async function saveImport(input:any[]){if(!shop)throw Error('Tạo hoặc chọn shop trước.');const clean=normalizeOrders(input);for(let i=0;i<clean.length;i+=50)await mutate('/api/store',{action:'import',orders:clean.slice(i,i+50)});await refresh();setPreview(null);setManual(false);tell('Đã lưu '+clean.length+' đơn. Đơn cũ được cập nhật, video được giữ nguyên.');}
 async function run(f:()=>Promise<any>){if(busy)return;setBusy(true);setError('');try{await f();}catch(e){fail(e);}finally{setBusy(false);}}
